package main

import (
	"encoding/base64"
	"strconv"
	"strings"
)

// Accounts 把账户名映射到口令。
type Accounts map[string]string

// basicScheme 是 Basic 认证头值的固定前缀（含结尾空格）。
const basicScheme = "Basic "

// DefaultRealm 是 realm 为空时使用的默认域。
const DefaultRealm = "Authorization Required"

// AuthorizationHeader 生成形如 "Basic <base64(user:password)>" 的头值。
func AuthorizationHeader(user, password string) string {
	return basicScheme + base64.StdEncoding.EncodeToString([]byte(user+":"+password))
}

// Challenge 生成 401 响应里的 WWW-Authenticate 头值；realm 为空时取默认域。
func Challenge(realm string) string {
	if realm == "" {
		realm = DefaultRealm
	}
	return "Basic realm=" + strconv.Quote(realm)
}

// Authenticate 校验请求头里的凭据，命中时返回账户名。
func Authenticate(accounts Accounts, authorization string) (string, bool) {
	if len(authorization) < len(basicScheme) {
		return "", false
	}
	if !strings.EqualFold(authorization[:len(basicScheme)], basicScheme) {
		return "", false
	}
	raw, err := base64.StdEncoding.DecodeString(authorization[len(basicScheme):])
	if err != nil {
		return "", false
	}
	cred := string(raw)
	i := strings.LastIndexByte(cred, ':')
	if i < 0 {
		return "", false
	}
	user, password := cred[:i], cred[i+1:]
	want, ok := accounts[user]
	if !ok || want != password {
		return "", false
	}
	return user, true
}

